package com.lankawings.servlet;
import com.lankawings.dao.*;import com.lankawings.model.Booking;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/reservations") public class BookingServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String pnr=r.getParameter("pnr");if(pnr!=null&&!pnr.isBlank()){Booking b=new BookingDAO().findByPnr(pnr);r.setAttribute("booking",b);if(b==null)r.setAttribute("error","No reservation was found for that PNR.");else {r.setAttribute("bookedSeats",new BookingDAO().bookedSeats(b.getFlightId()));r.setAttribute("flight",new FlightDAO().find(b.getFlightId()));}}}catch(Exception e){r.setAttribute("error",e.getMessage());}r.getRequestDispatcher("/reservations.jsp").forward(r,s);}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{BookingDAO d=new BookingDAO();int id=Integer.parseInt(r.getParameter("id"));String pnr=r.getParameter("pnr");try{if("cancel".equals(r.getParameter("action")))d.cancel(id);else d.updateDetails(id,r.getParameter("passengerName"),r.getParameter("passportNo"),r.getParameter("seatNumber"));s.sendRedirect(r.getContextPath()+"/reservations?pnr="+java.net.URLEncoder.encode(pnr,java.nio.charset.StandardCharsets.UTF_8)+"&ok=1");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}
}
